const items = $input.all();
return items.map(item => {
  const d = item.json;
  return {
    json: {
      name: d['Full Name'] || d['Name'] || '',
      email: d['Email Address'] || d['Email'] || '',
      resumeUrl: d['Resume'] || d['CV Link'] || '',
      role: d['sourceSheet'] === 'SWE' ? 'Software Engineer' : 'Business Development Manager',
      sourceRow: d['sourceRow'],
      sourceSheet: d['sourceSheet'],
      applied_at: d['Timestamp'] || new Date().toISOString(),
      status: 'processing',
      email_status: 'pending'
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;

  const url = data.resumeUrl || '';

  let fileId = '';

  // Format:
  // https://drive.google.com/file/d/FILE_ID/view
  let match = url.match(/\/d\/([a-zA-Z0-9_-]+)/);

  if (match) {
    fileId = match[1];
  } else {
    // Format:
    // https://drive.google.com/open?id=FILE_ID
    match = url.match(/[?&]id=([a-zA-Z0-9_-]+)/);

    if (match) {
      fileId = match[1];
    }
  }

  return {
    json: {
      ...data,
      fileId,
      downloadUrl: fileId
        ? `https://drive.google.com/uc?export=download&id=${fileId}`
        : null
    }
  };
});

const items = $input.all();

return items.map(item => {
  const binary = item.binary;
  const fileKey = binary ? Object.keys(binary)[0] : null;
  const data = fileKey ? binary[fileKey] : null;

  // Use metadata (always reliable, even with filesystem-v2 storage)
  const fileName = data?.fileName || '';
  const fileExt = (data?.fileExtension || '').toLowerCase();
  const mimeType = data?.mimeType || '';
  const fileSize = data?.fileSize || 0;
  const base64 = data?.data || '';

  // Detect if n8n stored it as filesystem reference
  const isFilesystemRef = base64.startsWith('filesystem');

  let status = 'valid';
  let reason = '';
  let fileType = fileExt.toUpperCase();

  if (!data || fileSize === 0) {
    status = 'invalid';
    reason = 'File download failed - empty';
  } else if (fileSize < 1000) {
    status = 'invalid';
    reason = 'File too small to be a valid CV';
  } else if (!isFilesystemRef) {
    // Only check base64 signatures if data is actually inline
    const isHTML = base64.includes('PCFET0NU') || base64.includes('<!DOCTYPE');
    const isPDF = base64.startsWith('JVBER');
    const isJPEG = base64.startsWith('/9j/');
    const isPNG = base64.startsWith('iVBOR');

    if (isHTML) {
      status = 'invalid';
      reason = 'Google Drive returned error page - file not accessible';
      fileType = 'HTML_ERROR';
    } else if (!isPDF && !isJPEG && !isPNG) {
      status = 'invalid';
      reason = 'Unsupported file format';
    }
  }

  // Also validate by extension/mime as backup
  const validExts = ['pdf', 'jpg', 'jpeg', 'png'];
  const validMimes = ['application/pdf', 'image/jpeg', 'image/png'];

  if (status === 'valid' && !validExts.includes(fileExt) && !validMimes.includes(mimeType)) {
    status = 'invalid';
    reason = 'Unsupported file format - only PDF, JPG, PNG accepted';
  }

  return {
    json: {
      ...item.json,
      fileBase64: isFilesystemRef ? 'filesystem-ref' : base64.substring(0, 100),
      fileMimeType: mimeType,
      _validation: {
        status: status,
        reason: reason,
        fileType: fileType,
        size: fileSize,
        isFilesystemRef: isFilesystemRef
      }
    },
    binary: item.binary
  };
});

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binaryKey = Object.keys(item.binary || {})[0];
  const mimeType = item.binary?.[binaryKey]?.mimeType || 'image/jpeg';

  // Correct way to read binary in n8n
  const buffer = await this.helpers.getBinaryDataBuffer(i, binaryKey);
  const base64 = buffer.toString('base64');

  results.push({
    json: {
      ...item.json,
      fileBase64: base64,
      fileMimeType: mimeType
    },
    binary: item.binary
  });
}

return results;

// 1. Gemini API response (from HTTP Request node, via $input)
const gemini = $input.first().json;
const text = gemini.candidates?.[0]?.content?.parts?.[0]?.text || '';

// 2. Applicant data from the node BEFORE HTTP Request
const applicant = $(' Convert to Base64').item.json;

// 3. Parse Gemini JSON text
let parsed = {};
try {
  const clean = text.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
  const jsonMatch = clean.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : '{}');
} catch (e) {
  parsed = {};
}

// 4. STRICT name match
const appName = (applicant.name || '').toLowerCase().trim();
const cvName = (parsed.extractedName || '').toLowerCase().trim();

function nameMatch(a, b) {
  if (!a || !b) return false;
  const cleanA = a.replace(/\s+/g, ' ').trim();
  const cleanB = b.replace(/\s+/g, ' ').trim();
  if (cleanA === cleanB) return true;
  if (cleanA.includes(cleanB) || cleanB.includes(cleanA)) return true;
  return false;
}

const namesMatch = nameMatch(appName, cvName);
const isTemplateFraud = (parsed.mismatchReason || '').toLowerCase().includes('placeholder') ||
                        (parsed.mismatchReason || '').toLowerCase().includes('template');

const isApplicantsResume = (parsed.isApplicantsResume !== false) && namesMatch && !isTemplateFraud;

return {
  json: {
    // Applicant data
    name: applicant.name,
    email: applicant.email,
    role: applicant.role || applicant.sourceSheet,
    sourceSheet: applicant.sourceSheet,
    sourceRow: applicant.sourceRow,

    // Gemini results
    isApplicantsResume: isApplicantsResume,
    mismatchReason: !namesMatch 
      ? `Name mismatch: app="${appName}", CV="${cvName}"` 
      : parsed.mismatchReason || null,
    score: parsed.score || 0,
    classification: parsed.classification || 'Weak',
    summary: parsed.summary || '',
    strengths: parsed.strengths || [],
    concerns: parsed.concerns || [],
    recommendation: parsed.recommendation || 'reject',
    extractedName: parsed.extractedName || 'Unknown',
    yearsExperience: parsed.yearsExperience || 0,
    skills: parsed.skills || [],
    education: parsed.education || 'Not found',
    justification: parsed.justification || ''
  }
};
